// StageChangeRequest One change to stage. Which fields apply depends on target and action:
//
//   - resource create: `name`, `kind`, `spec`, optional `region_id`
//   - resource update: `resource_id`, and `name` and/or `spec` (a full replacement, as PATCH takes)
//   - resource delete: `resource_id`, and `confirm` (the name) for databases
//   - variable create/update: `resource_id` (or `resource_name` for a service staged in this changeset),
//     `key`, `value`, `secret`, `sealed`
//   - variable delete: `resource_id`, `key`
//   - shared_variable create/update: `key`, `value`, `secret`, `sealed`; delete: `key`
//   - connection create: `from_resource` and `to_resource` (resource names, existing or staged); delete: `connection_id`
type StageChangeRequest struct {
	Action       ChangeAction            `json:"action"`
	Confirm      *string                 `json:"confirm,omitempty"`
	ConnectionId *openapi_types.UUID     `json:"connection_id,omitempty"`
	FromResource *string                 `json:"from_resource,omitempty"`
	Key          *string                 `json:"key,omitempty"`
	Kind         *ResourceKind           `json:"kind,omitempty"`
	Name         *string                 `json:"name,omitempty"`
	RegionId     *string                 `json:"region_id,omitempty"`
	ResourceId   *openapi_types.UUID     `json:"resource_id,omitempty"`
	ResourceName *string                 `json:"resource_name,omitempty"`
	Sealed       *bool                   `json:"sealed,omitempty"`
	Secret       *bool                   `json:"secret,omitempty"`
	Spec         *map[string]interface{} `json:"spec,omitempty"`
	Target       ChangeTarget            `json:"target"`
	ToResource   *string                 `json:"to_resource,omitempty"`

	// Value May contain references: ${{<service>.<KEY>}} for another service in this environment, or ${{shared.<KEY>}} for a shared variable
	Value *string `json:"value,omitempty"`
}

